import unreal
actor=None
for candidate in unreal.ObjectIterator(unreal.Actor):
    try:
        world=candidate.get_world()
        if candidate.get_actor_label()=='SSPR_M2A_TemporalOrchestrator' and world and 'UEDPIE' in world.get_path_name(): actor=candidate; break
    except Exception: pass
if actor is None: raise RuntimeError('Runtime M2-A actor not found')
methods=[name for name in dir(actor) if 'reset' in name.lower() or 'temporal' in name.lower()]
called=False
error=None
try:
    if hasattr(actor,'reset_temporal_history'):
        actor.reset_temporal_history(); called=True
except Exception as exc:
    error=str(exc)
print('M2A_RESET_EVENT='+repr({'methods':methods,'called':called,'error':error,'historyValid':actor.get_editor_property('HistoryValidValue'),'cameraValid':actor.get_editor_property('CameraDataValid'),'latest':actor.get_editor_property('LatestHistory').get_path_name()}))
